 "content": "def transform(grid):
    """Complete any diagonal segment joining aligned 1 markers; crossing 6s emit perpendicular diagonals."""
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    ones = [(r, c) for r in range(h) for c in range(w) if out[r][c] == 1]

    # Find all diagonal 1-pairs. In ordinary demos there is one pair; with
    # additional unrelated markers, only same-diagonal pairs define segments.
    pairs = []
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            if r1 != r2 and abs(r2 - r1) == abs(c2 - c1):
                pairs.append((abs(r2-r1), r1, c1, r2, c2))
    if not pairs:
        return out

    # Select the longest aligned pair, which identifies the intended drawn
    # segment even if unrelated 1 markers are present elsewhere.
    _, r1, c1, r2, c2 = max(pairs)
    dr = 1 if r2 > r1 else -1
    dc = 1 if c2 > c1 else -1

    segment = []
    r, c = r1, c1
    while True:
        segment.append((r, c))
        if (r, c) == (r2, c2):
            break
        r += dr
        c += dc

    # Sixes on the segment remain as markers and launch perpendicular lines.
    seeds = [(r, c) for r, c in segment if grid[r][c] == 6]
    for r, c in segment:
        if out[r][c] != 6:
            out[r][c] = 1

    for sr, sc in seeds:
        for sign in (-1, 1):
            rr, cc = sr, sc
            while 0 <= rr < h and 0 <= cc < w:
                if out[rr][cc] not in (1, 6):
                    out[rr][cc] = 6
                rr += sign * dr
                cc -= sign * dc

    return out
